impl ProjectViaOriginOnto<MultiVector> for Horizon {
    type Output = MultiVector;
    // Operative Statistics for this implementation:
    //           add/sub      mul      div      pow
    //      f32        4       14        0        0
    //    simd2        0        1        0      N/A
    //    simd3        4        9        0      N/A
    //    simd4        0        2        0      N/A
    // Totals...
    // yes simd        8       26        0      N/A
    //  no simd       16       51        0        0
    fn project_via_origin_onto(self, other: MultiVector) -> Self::Output {
        use crate::elements::*;
        let wedge_g0_y = self[e3215] * other[e1234];
        let wedge_g10 = self[e3215] * other[e12345] * -1.0;
        MultiVector::from_groups(
            // scalar, e12345
            Simd32x2::from([(wedge_g0_y * other[scalar]) + (wedge_g10 * other[e4]), wedge_g0_y * other[e12345]]),
            // e1, e2, e3, e4
            ((Simd32x3::from(wedge_g0_y) * other.group1().xyz()) + (Simd32x3::from(wedge_g10) * other.group3().xyz())).with_w(wedge_g0_y * other[e4]),
            // e5
            (wedge_g0_y * other[e5]) + (wedge_g10 * other[e45]),
            // e41, e42, e43, e45
            Simd32x4::from(wedge_g0_y) * other.group3(),
            // e15, e25, e35
            (Simd32x3::from(wedge_g0_y) * other.group4()) + (Simd32x3::from(wedge_g10) * other.group6().xyz()),
            // e23, e31, e12
            (Simd32x3::from(wedge_g0_y) * other.group5()) + (Simd32x3::from(wedge_g10) * other.group7()),
            // e415, e425, e435, e321
            (Simd32x2::from(wedge_g0_y) * other.group6().xy()).with_zw(wedge_g0_y * other[e435], (wedge_g0_y * other[e321]) + (wedge_g10 * other[e1234])),
            // e423, e431, e412
            Simd32x3::from(wedge_g0_y) * other.group7(),
            // e235, e315, e125
            (Simd32x3::from(wedge_g0_y) * other.group8()) + (Simd32x3::from(wedge_g10) * other.group9().yzw()),
            // e1234, e4235, e4315, e4125
            Simd32x4::from(wedge_g0_y) * other.group9(),
            // e3215
            (wedge_g0_y * other[e3215]) + (wedge_g10 * other[e12345]),
        )
    }
}
