    //  no simd       91      118        0        0
    fn project_via_origin_onto(self, other: MultiVector) -> Self::Output {
        use crate::elements::*;
        let right_dual_g0 = other.group0().yx() * Simd32x2::from([-1.0, 1.0]);
        let wedge_g0_y = (other[e1234] * self[e3215]) + (other[e3215] * self[e1234]);
        let wedge_g9 = Simd32x4::from([right_dual_g0[0] * self[e1234], 0.0, 0.0, 0.0]);
        let wedge_g10 = right_dual_g0[0] * self[e3215];
        MultiVector::from_groups(
            // scalar, e12345
            Simd32x2::from([
                (wedge_g0_y * other[scalar])
                    + (wedge_g10 * other[e4])
                    + (wedge_g9[0] * other[e5])
                    + (wedge_g9[1] * other[e1])
                    + (wedge_g9[2] * other[e2])
                    + (wedge_g9[3] * other[e3]),
                wedge_g0_y * other[e12345],
            ]),
            // e1, e2, e3, e4
            (Simd32x4::from(wedge_g0_y) * other.group1())
                + Simd32x3::from(0.0).with_w(-(wedge_g9[2] * other[e42]) - (wedge_g9[3] * other[e43]))
                + (Simd32x3::from(wedge_g10) * other.group3().xyz()).with_w(0.0)
                + (other.group5().yzx() * wedge_g9.wyz()).with_w(0.0)
                - (Simd32x4::from(wedge_g9[0]) * Simd32x4::from([other[e15], other[e25], other[e35], other[e45]]))
                - (wedge_g9.zwyy() * other.group5().zxy().with_w(other[e41])),
            // e5
            (wedge_g0_y * other[e5]) + (wedge_g10 * other[e45]) + (wedge_g9[1] * other[e15]) + (wedge_g9[2] * other[e25]) + (wedge_g9[3] * other[e35]),
            // e41, e42, e43, e45
            (Simd32x4::from(wedge_g0_y) * other.group3())
                + Simd32x3::from(0.0).with_w(-(wedge_g9[2] * other[e425]) - (wedge_g9[3] * other[e435]))
                + (Simd32x3::from(wedge_g9[0]) * other.group6().xyz()).with_w(0.0)
                + (other.group7().zxy() * wedge_g9.zwy()).with_w(0.0)
                - (wedge_g9.wyzy() * other.group7().yzx().with_w(other[e415])),
            // e15, e25, e35
            (Simd32x3::from(wedge_g0_y) * other.group4()) + (Simd32x3::from(wedge_g10) * other.group6().xyz()) + (other.group8().yzx() * wedge_g9.wyz())
                - (other.group8().zxy() * wedge_g9.zwy()),
            // e23, e31, e12
            (Simd32x3::from(wedge_g0_y) * other.group5()) + (Simd32x3::from(wedge_g10) * other.group7()) + (Simd32x3::from(wedge_g9[0]) * other.group8())
                - (Simd32x3::from(other[e321]) * wedge_g9.yzw()),
            // e415, e425, e435, e321
            (Simd32x4::from(wedge_g0_y) * other.group6()) + (Simd32x4::from([wedge_g9[2], wedge_g9[3], wedge_g9[1], wedge_g10]) * other.group9().wyzx())
                - (Simd32x4::from([other[e4315], other[e4125], other[e4235], other[e3215]]) * wedge_g9.wyzx()),
            // e423, e431, e412
            (Simd32x3::from(wedge_g0_y) * other.group7()) + (Simd32x3::from(other[e1234]) * wedge_g9.yzw()) - (Simd32x3::from(wedge_g9[0]) * other.group9().yzw()),
            // e235, e315, e125
            (Simd32x3::from(wedge_g0_y) * other.group8()) + (Simd32x3::from(wedge_g10) * other.group9().yzw()) - (Simd32x3::from(other[e3215]) * wedge_g9.yzw()),
            // e1234, e4235, e4315, e4125
            (wedge_g9 * Simd32x4::from(other[e12345])) + (Simd32x4::from(wedge_g0_y) * other.group9()),
            // e3215
            (wedge_g0_y * other[e3215]) + (wedge_g10 * other[e12345]),
        )
    }
